import pytest


def test_invariant_basic_ten_percent():
    from shop.pricing import apply_discount
    assert apply_discount(100.0, 10.0) == pytest.approx(90.0), "10% off 100 is 90"


def test_invariant_zero_pct_unchanged():
    from shop.pricing import apply_discount
    assert apply_discount(50.0, 0.0) == pytest.approx(50.0), "0% leaves price unchanged"


def test_invariant_zero_price_stays_zero():
    from shop.pricing import apply_discount
    assert apply_discount(0.0, 10.0) == pytest.approx(0.0), "zero price stays zero"


def test_invariant_hundred_pct_free():
    from shop.pricing import apply_discount
    assert apply_discount(50.0, 100.0) == pytest.approx(0.0), "100% off is free"


def test_invariant_over_hundred_clamped_to_zero():
    from shop.pricing import apply_discount
    assert apply_discount(50.0, 150.0) == pytest.approx(0.0), "over 100% is free not negative"


def test_invariant_very_large_price():
    from shop.pricing import apply_discount
    assert apply_discount(1e12, 10.0) == pytest.approx(9e11), "large price discounts proportionally"


def test_invariant_bulk_empty_total_zero():
    from shop.pricing import bulk_price
    assert bulk_price([], 10.0) == pytest.approx(0.0), "empty bulk total is zero"


def test_invariant_bulk_total_matches_discounts():
    from shop.pricing import bulk_price
    assert bulk_price([10.0, 20.0], 10.0) == pytest.approx(27.0), "bulk sums discounted prices"


def test_invariant_bulk_over_hundred_free():
    from shop.pricing import bulk_price
    assert bulk_price([10.0, 20.0], 200.0) == pytest.approx(0.0), "bulk over 100% is free"


def test_invariant_bulk_rounded_to_cents():
    from shop.pricing import bulk_price
    assert bulk_price([1.111, 2.222], 0.0) == pytest.approx(3.33), "bulk total rounded to cents"

