def test_invariant_empty_cart():
    from shop.cart import cart_count
    assert cart_count([]) == 0, "empty cart has 0 units"


def test_invariant_single_item():
    from shop.cart import cart_count
    assert cart_count([("apple", 2)]) == 2, "single item returns its quantity"


def test_invariant_multiple_items_sum():
    from shop.cart import cart_count
    assert cart_count([("apple", 1), ("banana", 3), ("cherry", 2)]) == 6, "quantities are summed"


def test_invariant_zero_quantities():
    from shop.cart import cart_count
    assert cart_count([("apple", 0), ("banana", 5), ("cherry", 0)]) == 5, "zero quantities contribute 0"


def test_invariant_very_large_quantities():
    from shop.cart import cart_count
    assert cart_count([("apple", 10**9), ("banana", 10**9)]) == 2 * 10**9, "large quantities sum exactly"
